 CREATE OR REPLACE FUNCTION public.offencehistory(i_evalutionid uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
  RETURNS TABLE(youthname character varying, youthid character varying, folderid character varying, birthdate character varying, race character varying, gender character varying, legal_incident_date character varying, placement_details json, appeal_details json, complaint_details json, petition_details json, court_details json, offense_details json)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
    BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
         RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
            select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 CAST(p.firstname||' '||p.lastname as character varying) as youthname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 CAST(p.cjamspid as character varying) as youthid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 INTSR.intakenumber as folderid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                 CAST(to_char(p.dob,'MM/DD/YYYY') as character varying) as birthdate,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 (select distinct typedescription from racetype where racetypekey=p.racetypekey) as race,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 (select distinct typedescription from gendertype where gendertypekey=p.gendertypekey) as gender,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 cast(to_char(inve.complaintreceiveddate,'MM/DD/YYYY') as character varying) as legal_incident_date,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             json_agg(json_build_object('provider_name',coalesce(pr.providername,' '),'admission_type',coalesce((select distinct description from placementadmissiontype where placementadmissiontypekey=pl.placementadmissiontypekey),' '),'admission_classification',coalesce((select distinct description from placementadmissionclassification where placementadmissionclassificationkey=pl.placementadmissionclassificationkey),' '),'status',coalesce(pl.statustypekey,' '),'admission_date',coalesce(to_char(pl.addate,'MM/DD/YYYY'),' '),'release_date',coalesce(to_char(pl.releasedate,'MM/DD/YYYY'),' ') ) )  as placement_details,                                                                                                                                                                                                                                                      
             json_agg(json_build_object('appeal_date',coalesce(to_char(ia.appealdate,'MM/DD/YYYY'),' '),'appeal_status',coalesce(ia.appealstatus,' '),'appeal_comments',coalesce(ia.remarks,' ') )) as appeal_details ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                  json_agg(json_build_object('complaint_id',cast(inve.complaintid as character varying),'complaint_date',coalesce(to_char(inve.complaintreceiveddate,'MM/DD/YYYY'),' '),'arrest_date',coalesce(to_char(inve.arrestdate,'MM/DD/YYYY'),' '),'county',coalesce((select distinct countyname from county where countyid=inve.countyid),' '),'zipcode',inve.zipcode,'decision',coalesce((select distinct description from dispositioncode where dispositioncode =srtcdc.dispositioncode),' '),'complaintsource',coalesce((select distinct description from evaluationsourceagency where evaluationsourcetypekey=es.evaluationsourcekey),' '),'complainantname',coalesce(es.lastname,' ') ||' '|| coalesce(es.firstname,' '),'complainantaddress',coalesce(es.streetno,' ') ||' '||coalesce(es.street1,' ')||' '||coalesce(es.street2,' '),'complainantphone',' ')) as complaint_details ,
             json_agg(json_build_object('petition_id',pe.petitionid,'complaint_id',inve.complaintid,'petetion_date',coalesce(to_char(pe.petitiondate,'MM/DD/YYYY'),' '),'petetion_type',coalesce((select distinct description from petitiontype where petitiontypekey=pe.petitiontypekey),' '),'petetion_notes',coalesce(pe.hearingnotes,' ') )) as petition_details,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
             json_agg(json_build_object('petition_id',pe.petitionid,'court_date',coalesce(to_char(ca.hearingdatetime,'MM/DD/YYYY'),' '),'court_action',coalesce((select distinct description from courtactiontype where courtactiontypekey=ca.courtactiontypekey),' '),'dispositions',coalesce((select distinct description from courtordertype where courtordertypekey=ca.courtordertypekey),' '),'legal_council',coalesce(ca.legalcounselname,' '),'judge',coalesce(ca.magistratename,' '),'termination_date',coalesce(to_char(ca.terminationdatetime,'MM/DD/YYYY'),' '),'conditions',coalesce((select distinct description from conditiontype where conditiontypekey=ca.conditiontypekey),' ') ))  as court_details,                                                                                                                                                                            
             json_agg(json_build_object('complaint_id',inve.complaintid,'petition_id',pe.petitionid,'Offence_name',(select distinct AG.name  from  allegation AG join intakeservicerequestevaluationconfig ITSEC  on ITSEC.allegationid=AG.allegationid and AG.activeflag=1 where  ITSEC.intakeservicerequestevaluationid=inve.intakeservicerequestevaluationid and ITSEC.activeflag=1 ),'Offence_date',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
              case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                  when inve.unknownrange=0 then to_char(inve.offensedate,'MM/DD/YYYY')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                  when inve.unknownrange=1 then to_char(inve.offensedate,'MM/DD/YYYY')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                  when inve.unknownrange=2 then to_char(inve.begindate,'MM/DD/YYYY')|| ' - ' || to_char(inve.enddate,'MM/DD/YYYY')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
              end ,'adjudicated_date',coalesce(to_char(ca.adjudicationdatetime,'MM/DD/YYYY'),' '),'adjudicated_decision',coalesce(ca.adjudicationdecision,' '),'adjudicated_offense',coalesce(case when ca.adjudicationdecision='Sustained' then AG.name else NULL end,' ') ,'victime_name',coalesce(victim_details.victimname,' '),'victim_adress',coalesce(victim_details.victimaddress,' '),'victim_phone',coalesce(victim_details.victimphonenumber,' ') )) as offense_details                                                                                                                                                                                                                                                                                                                                                                                                                 
             from intakeservicerequestevaluation inve                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
              join intakeservicerequest INTSR on INTSR.intakenumber=inve.intakenumber and INTSR.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
              join intakeservicerequestactor INSRA on INSRA.intakeserviceid=INTSR.intakeserviceid and INSRA.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
              join actor ACC on ACC.actorid=INSRA.actorid and ACC.activeflag=1 and ACC.actortype='Youth'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
              join person p on ACC.personid=p.personid and p.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
              left join evaluationsource es on es.evaluationsourceid=inve.evaluationsourceid and es.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
              left join  intakeservicerequestdispositioncode isrdc ON INTSR.intakeserviceid = isrdc.intakeserviceid AND isrdc.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
              left join  servicerequesttypeconfigdispositioncode srtcdc ON isrdc.servicerequesttypeconfigiddispostionid = srtcdc.servicerequesttypeconfigiddispostionid AND srtcdc.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
              left join servicerequestappointment sap on sap.intakeserviceid=INTSR.intakeserviceid and sap.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                          join intakeservicerequestevaluationconfig ITSEC on ITSEC.intakeservicerequestevaluationid=inve.intakeservicerequestevaluationid and ITSEC.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
              join allegation AG on ITSEC.allegationid=AG.allegationid and AG.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
              left join placement pl on INTSR.intakeserviceid =pl.intakeserviceid and pl.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
              left JOIN provider pr ON pl.providerid = pr.providerid AND pr.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                          left join intakeappeal ia on INTSR.intakenumber=ia.intakenumber and ia.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                          left join intakeservicerequestpetition pe on INTSR.intakeserviceid =pe.intakeservicerequestid and pe.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                          left join intakeservicerequestcourtaction ca on INTSR.intakeserviceid=ca.intakeservicerequestid and ca.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
              left join                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             (select INTSR.intakenumber as intakenumber,p.lastname ||' '|| p.firstname as victimname, pa.address || ' ' || pa.address2 || ' ' ||pa.county || ' ' || pa.state || ' ' || pa.zipcode victimaddress,pp.phonenumber victimphonenumber from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
               intakeservicerequest INTSR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
               left join intakeservicerequestactor INSRA on INSRA.intakeserviceid=INTSR.intakeserviceid and INSRA.activeflag=1 and INSRA.intakeservicerequestpersontypekey='Victim'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
               left join actor ACC on ACC.actorid=INSRA.actorid and ACC.activeflag=1 and ACC.actortype='Victim'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
               left join person p on ACC.personid=p.personid and p.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
               left join personaddress pa on p.personid=pa.personid and pa.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             left join personphonenumber pp on p.personid=pp.personid and pp.activeflag=1) victim_details                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
               on INTSR.intakenumber=victim_details.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
               where  inve.intakeservicerequestevaluationid = i_evalutionid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
               group by                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                youthname,youthid,folderid,birthdate,race,gender,legal_incident_date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
              ) ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
    end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
   $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        

